args.command:
for part in host key value; do
echo "=== $part ==="
for i in $(seq 33 126); do
  c=$(printf "\\$(printf '%03o' $i)")
  case $part in
    host) line="http://a${c}b.co/x";;
    key)  line="http://e.com/p?k${c}k=v";;
    value) line="http://e.com/p?k=v${c}v";;
  esac
  out=$(printf '%s\n' "$line" | ./executable --enable=urls | sed -e 's/\x1b\[[0-9;]*m/|/g')
  case $part in
    host) got=$(printf '%s' "$out" | sed -n 's#.*://|\([^|]*\)|.*#\1#p'); want="a${c}b.co";;
    key)  got=$(printf '%s' "$out" | sed -n 's#.*|?||\([^|]*\)|.*#\1#p'); want="k${c}k";;
    value) got=$(printf '%s' "$out" | sed -n 's#.*|=||\([^|]*\)|.*#\1#p'); want="v${c}v";;
  esac
  if [ "$got" != "$want" ]; then printf '%s-stop %d %q\n' $part $i "$c"; fi
done
done

