args.content:
#!/usr/bin/env python3
import subprocess, tempfile, os, sys

EXE = './executable'
STYLE = 'fg = "bright_green"\nbg = "bright_yellow"\nbold = true\nitalic = true\nunderline = true\nfaint = true'

LINES = {
 'main': 'ERROR WARN INFO DEBUG TRACE true false null GET POST PUT PATCH DELETE 42 3.14 12:34:56 2022-09-09 2022-09-09T12:34:56.789Z "quoted" a=b /usr/local/bin http://h.co/p?k=v 0x12345678 0x1234567890abcdef 10.0.0.1 2001:db8::1 5f7d1bce-81ab-4a87-af78-9a37f26c58b1 name[1]: x\n',
 'json': '{"k": "v", "n": 1}\n',
}

def run(toml_text, line):
    with open('/tmp/probe.toml','w') as f: f.write(toml_text)
    return subprocess.run([EXE,'--config-path','/tmp/probe.toml'], input=line.encode(), capture_output=True).stdout

defaults = {k: run('', v) for k,v in LINES.items()}

candidates = sys.argv[1:]
for name in candidates:
    for lk, line in LINES.items():
        out = run('[[%s]]\n%s\n' % (name, STYLE), line)
        if out != defaults[lk]:
            print('HIT %s (%s)' % (name, lk))

